const STARTERS=[{"id":"er-001","level":1,"segments":["The students","were interested","on the lecture","about modern art"],"answer":2,"correction":"in the lecture","category":"Preposition","explanation":"The adjective 'interested' normally takes the preposition 'in' before the thing or topic that interests someone.","rule":"be interested in + noun","wolf":false},{"id":"er-002","level":1,"segments":["The students","was","excited","about the trip"],"answer":1,"correction":"were","category":"Subject–Verb Agreement","explanation":"The plural subject 'students' requires the plural past form 'were'.","rule":"plural subject + were","wolf":false},{"id":"er-003","level":1,"segments":["My brother","go","to the library","every Saturday"],"answer":1,"correction":"goes","category":"Subject–Verb Agreement","explanation":"A third-person singular subject in the simple present takes a verb ending in -s/-es.","rule":"he/she/it + verb-s","wolf":false},{"id":"er-004","level":1,"segments":["She bought","a umbrella","at the market","yesterday"],"answer":1,"correction":"an umbrella","category":"Articles","explanation":"Use 'an' before a word that begins with a vowel sound.","rule":"an + vowel sound","wolf":false},{"id":"er-005","level":1,"segments":["The child","plays","happy","in the garden"],"answer":2,"correction":"happily","category":"Adjective vs Adverb","explanation":"The word modifies the verb 'plays', so an adverb is required.","rule":"verb + adverb","wolf":false},{"id":"er-006","level":1,"segments":["These books","belongs","to my sister","in Jakarta"],"answer":1,"correction":"belong","category":"Subject–Verb Agreement","explanation":"The plural subject 'books' takes the base-form plural verb 'belong'.","rule":"plural subject + base verb","wolf":false},{"id":"er-007","level":1,"segments":["We","did not went","to school","on Monday"],"answer":1,"correction":"did not go","category":"Verb Form","explanation":"After the auxiliary 'did', use the base form of the main verb.","rule":"did + not + base verb","wolf":false},{"id":"er-008","level":1,"segments":["The news","are","surprising","today"],"answer":1,"correction":"is","category":"Subject–Verb Agreement","explanation":"'News' is grammatically singular even though it ends in -s.","rule":"news + singular verb","wolf":false},{"id":"er-009","level":1,"segments":["My father","gave me","an useful","dictionary"],"answer":2,"correction":"a useful","category":"Articles","explanation":"'Useful' begins with the consonant sound /j/, so it takes 'a', not 'an'.","rule":"a + consonant sound","wolf":false},{"id":"er-010","level":1,"segments":["They","enjoy to swim","in the pool","after class"],"answer":1,"correction":"enjoy swimming","category":"Gerund/Infinitive","explanation":"The verb 'enjoy' is followed by a gerund, not a to-infinitive.","rule":"enjoy + verb-ing","wolf":false},{"id":"er-011","level":1,"segments":["The soup","tastes","deliciously","this evening"],"answer":2,"correction":"delicious","category":"Linking Verbs","explanation":"After the linking verb 'taste', use an adjective to describe the subject.","rule":"linking verb + adjective","wolf":false},{"id":"er-012","level":1,"segments":["I have","two childs","at home","with my wife"],"answer":1,"correction":"two children","category":"Noun Number","explanation":"The plural of 'child' is the irregular form 'children'.","rule":"child → children","wolf":false},{"id":"er-013","level":1,"segments":["She","can speaks","English","very well"],"answer":1,"correction":"can speak","category":"Modal Verbs","explanation":"A modal verb such as 'can' is followed by the base form of the verb.","rule":"modal + base verb","wolf":false},{"id":"er-014","level":1,"segments":["We saw","three woman","waiting","at the station"],"answer":1,"correction":"three women","category":"Noun Number","explanation":"The plural of 'woman' is 'women'.","rule":"woman → women","wolf":false},{"id":"er-015","level":1,"segments":["The furniture","in this room","are","very old"],"answer":2,"correction":"is","category":"Subject–Verb Agreement","explanation":"'Furniture' is an uncountable singular noun and takes a singular verb.","rule":"uncountable noun + singular verb","wolf":false},{"id":"er-016","level":1,"segments":["He","usually","drinks coffee","at mornings"],"answer":3,"correction":"in the mornings","category":"Preposition","explanation":"For a repeated part of the day, 'in the morning(s)' is the standard expression.","rule":"in the morning(s)","wolf":false},{"id":"er-017","level":1,"segments":["They","were","very tired","because the long trip"],"answer":3,"correction":"because of the long trip","category":"Because vs Because of","explanation":"'Because' introduces a clause; before a noun phrase, use 'because of'.","rule":"because of + noun phrase","wolf":false},{"id":"er-018","level":1,"segments":["The dog","run","across the yard","every morning"],"answer":1,"correction":"runs","category":"Subject–Verb Agreement","explanation":"A singular third-person subject in the simple present takes 'runs'.","rule":"singular subject + verb-s","wolf":false},{"id":"er-019","level":1,"segments":["She","has","less books","than I do"],"answer":2,"correction":"fewer books","category":"Countable Nouns","explanation":"Use 'fewer' with plural countable nouns such as 'books'.","rule":"fewer + plural countable noun","wolf":false},{"id":"er-020","level":1,"segments":["The teacher","asked us","to be quietly","during the test"],"answer":2,"correction":"to be quiet","category":"Adjective vs Adverb","explanation":"After the linking verb 'be', use the adjective 'quiet'.","rule":"be + adjective","wolf":false},{"id":"er-021","level":1,"segments":["There","is","many students","in the hall"],"answer":1,"correction":"are","category":"Quantifiers","explanation":"In an existential 'there' construction, the verb agrees with the following plural noun 'many students'.","rule":"there are + plural noun","wolf":false},{"id":"er-022","level":1,"segments":["My uncle","has lived","in Bandung","since ten years"],"answer":3,"correction":"for ten years","category":"Since vs For","explanation":"Use 'for' with a duration of time; 'since' introduces a starting point.","rule":"for + duration","wolf":false},{"id":"er-023","level":1,"segments":["The baby","is sleeping","peaceful","in the crib"],"answer":2,"correction":"peacefully","category":"Adjective vs Adverb","explanation":"The word modifies the action 'is sleeping', so the adverb 'peacefully' is needed.","rule":"verb + adverb","wolf":false},{"id":"er-024","level":1,"segments":["Those boxes","is","too heavy","for me"],"answer":1,"correction":"are","category":"Subject–Verb Agreement","explanation":"The plural subject 'boxes' requires 'are'.","rule":"plural subject + are","wolf":false},{"id":"er-025","level":1,"segments":["She","doesn't likes","spicy food","very much"],"answer":1,"correction":"doesn't like","category":"Verb Form","explanation":"After 'doesn't', the main verb must be in the base form.","rule":"doesn't + base verb","wolf":false},{"id":"er-026","level":2,"segments":["The company","has operated","since","five years"],"answer":2,"correction":"for","category":"Since vs For","explanation":"Use 'for' to express a duration such as five years.","rule":"for + duration","wolf":false},{"id":"er-027","level":2,"segments":["If it rains","tomorrow,","we will stayed","at home"],"answer":2,"correction":"we will stay","category":"Conditionals","explanation":"In the first conditional, the result clause uses 'will + base verb'.","rule":"if + present, will + base verb","wolf":false},{"id":"er-028","level":2,"segments":["The lecture","was so bored","that several students","fell asleep"],"answer":1,"correction":"was so boring","category":"Participial Adjectives","explanation":"A thing that causes boredom is 'boring'; a person who feels boredom is 'bored'.","rule":"thing + -ing adjective","wolf":false},{"id":"er-029","level":2,"segments":["She is","more smarter","than","her brother"],"answer":1,"correction":"smarter","category":"Comparatives","explanation":"Do not use both 'more' and the -er comparative ending together.","rule":"smart → smarter","wolf":false},{"id":"er-030","level":2,"segments":["The man","who car was stolen","reported it","to the police"],"answer":1,"correction":"whose car was stolen","category":"Relative Clauses","explanation":"Use 'whose' to show possession inside a relative clause.","rule":"whose + noun","wolf":false},{"id":"er-031","level":2,"segments":["We are looking forward","to meet","our new professor","next week"],"answer":1,"correction":"to meeting","category":"Gerund/Infinitive","explanation":"In 'look forward to', 'to' is a preposition and is followed by a gerund.","rule":"look forward to + verb-ing","wolf":false},{"id":"er-032","level":2,"segments":["He suggested","that we left","earlier","to avoid traffic"],"answer":1,"correction":"that we leave","category":"Subjunctive","explanation":"After 'suggest that', formal English commonly uses the base-form subjunctive.","rule":"suggest that + subject + base verb","wolf":false},{"id":"er-033","level":2,"segments":["I prefer","tea than coffee","in the morning","before work"],"answer":1,"correction":"tea to coffee","category":"Preposition","explanation":"With nouns, the standard comparison pattern is 'prefer X to Y'.","rule":"prefer X to Y","wolf":false},{"id":"er-034","level":2,"segments":["The equipment","were delivered","to the laboratory","on time"],"answer":1,"correction":"was delivered","category":"Subject–Verb Agreement","explanation":"'Equipment' is uncountable and grammatically singular.","rule":"equipment + singular verb","wolf":false},{"id":"er-035","level":2,"segments":["There were","too much people","at the event","last night"],"answer":1,"correction":"too many people","category":"Quantifiers","explanation":"Use 'many' with plural countable nouns such as 'people'.","rule":"many + plural countable noun","wolf":false},{"id":"er-036","level":2,"segments":["She explained","me the problem","very clearly","after class"],"answer":1,"correction":"the problem to me","category":"Verb Pattern","explanation":"'Explain' normally takes the thing explained directly and the person after 'to'.","rule":"explain something to someone","wolf":false},{"id":"er-037","level":2,"segments":["The book","that I borrowed it","from the library","was useful"],"answer":1,"correction":"that I borrowed","category":"Relative Clauses","explanation":"The relative pronoun already functions as the object, so the extra pronoun 'it' is unnecessary.","rule":"relative pronoun replaces object","wolf":false},{"id":"er-038","level":2,"segments":["By the time we arrived","the movie","already started","in the main theater"],"answer":2,"correction":"had already started","category":"Past Perfect","explanation":"Use the past perfect for an earlier past action completed before another past action.","rule":"by the time + past, had + past participle","wolf":false},{"id":"er-039","level":2,"segments":["He has worked","here","from 2020","as an engineer"],"answer":2,"correction":"since 2020","category":"Since vs For","explanation":"Use 'since' with a specific starting point.","rule":"since + starting point","wolf":false},{"id":"er-040","level":2,"segments":["The children","were made","clean the room","before lunch"],"answer":2,"correction":"to clean the room","category":"Passive Causative","explanation":"In the passive form, 'make' is followed by a to-infinitive.","rule":"be made to + base verb","wolf":false},{"id":"er-041","level":2,"segments":["The report","must submit","by Friday","to the manager"],"answer":1,"correction":"must be submitted","category":"Passive Voice","explanation":"The report receives the action, so the modal must be followed by 'be + past participle'.","rule":"modal + be + past participle","wolf":false},{"id":"er-042","level":2,"segments":["She is","enough old","to drive","a car"],"answer":1,"correction":"old enough","category":"Word Order","explanation":"With adjectives, 'enough' comes after the adjective.","rule":"adjective + enough","wolf":false},{"id":"er-043","level":2,"segments":["I have visited Bali","last year","with my family","during the holiday"],"answer":0,"correction":"I visited Bali","category":"Present Perfect vs Simple Past","explanation":"A finished past time expression such as 'last year' requires the simple past, not the present perfect.","rule":"finished past time → simple past","wolf":false},{"id":"er-044","level":2,"segments":["The manager","asked whether","had I finished","the task"],"answer":2,"correction":"I had finished","category":"Indirect Questions","explanation":"In an embedded or indirect question, use statement word order, not question inversion.","rule":"whether + subject + verb","wolf":false},{"id":"er-045","level":2,"segments":["The scientist","is responsible","of analyzing","the samples"],"answer":2,"correction":"for analyzing","category":"Preposition","explanation":"The adjective 'responsible' is followed by 'for'.","rule":"responsible for + noun/verb-ing","wolf":false},{"id":"er-046","level":2,"segments":["My parents","used to","living","in Surabaya"],"answer":2,"correction":"live","category":"Used To","explanation":"'Used to' is followed by the base form of the verb.","rule":"used to + base verb","wolf":false},{"id":"er-047","level":2,"segments":["This exercise","is much","more easier","than the previous one"],"answer":2,"correction":"easier","category":"Comparatives","explanation":"Do not combine 'more' with an adjective already marked by -er.","rule":"easy → easier","wolf":false},{"id":"er-048","level":2,"segments":["Neither the students","nor the teacher","were","prepared"],"answer":2,"correction":"was","category":"Subject–Verb Agreement","explanation":"With 'neither...nor', agreement usually follows the nearer subject; 'the teacher' is singular.","rule":"neither A nor B + verb agrees with nearer subject","wolf":false},{"id":"er-049","level":2,"segments":["The number of applicants","have increased","significantly","this year"],"answer":1,"correction":"has increased","category":"Subject–Verb Agreement","explanation":"The head of the subject is singular 'number', so the verb is singular.","rule":"the number of + plural noun + singular verb","wolf":false},{"id":"er-050","level":2,"segments":["She bought","a pair of","new leather shoes","and wore it"],"answer":3,"correction":"and wore them","category":"Pronoun Agreement","explanation":"The pronoun refers to plural 'shoes', so use 'them'.","rule":"plural antecedent → plural pronoun","wolf":false},{"id":"er-051","level":3,"segments":["Hardly","I had arrived","when the meeting","began"],"answer":1,"correction":"had I arrived","category":"Inversion","explanation":"After a negative limiting adverb such as 'hardly' at the beginning, invert the auxiliary and subject.","rule":"Hardly had + subject + past participle + when","wolf":false},{"id":"er-052","level":3,"segments":["If I had known","about the delay,","I would tell","you earlier"],"answer":2,"correction":"I would have told","category":"Third Conditional","explanation":"A past unreal condition takes 'would have + past participle' in the result clause.","rule":"if + had + pp, would have + pp","wolf":false},{"id":"er-053","level":3,"segments":["The professor recommended","that each student","submits","the paper online"],"answer":2,"correction":"submit","category":"Subjunctive","explanation":"After 'recommend that', formal English uses the base-form subjunctive.","rule":"recommend that + subject + base verb","wolf":false},{"id":"er-054","level":3,"segments":["Despite","he was tired,","he continued","working"],"answer":1,"correction":"being tired,","category":"Concession","explanation":"'Despite' is followed by a noun phrase or gerund, not a finite clause.","rule":"despite + noun/verb-ing","wolf":false},{"id":"er-055","level":3,"segments":["The new policy","is expected","to reducing","operating costs"],"answer":2,"correction":"to reduce","category":"Infinitive","explanation":"The infinitive marker 'to' is followed by the base form of the verb.","rule":"to + base verb","wolf":false},{"id":"er-056","level":3,"segments":["The woman","whom we thought","was the director","greeted us"],"answer":1,"correction":"who we thought","category":"Relative Clauses","explanation":"The relative pronoun is the subject of 'was the director', so the subject form 'who' is required.","rule":"who + verb; whom + subject + verb","wolf":false},{"id":"er-057","level":3,"segments":["The article","discusses about","several factors","affecting migration"],"answer":1,"correction":"discusses","category":"Verb Pattern","explanation":"'Discuss' is transitive and takes a direct object without 'about'.","rule":"discuss + noun","wolf":false},{"id":"er-058","level":3,"segments":["Having finished","the experiment,","the results","were recorded immediately"],"answer":2,"correction":"the researchers","category":"Dangling Modifiers","explanation":"The understood subject of 'Having finished' must be the person who finished the experiment, not 'the results'.","rule":"introductory participle must modify following subject","wolf":true},{"id":"er-059","level":3,"segments":["Not only the students","but also the instructor","were","confused by the schedule"],"answer":2,"correction":"was","category":"Subject–Verb Agreement","explanation":"With 'not only...but also', the verb commonly agrees with the nearer subject 'the instructor'.","rule":"not only A but also B + agreement with nearer subject","wolf":false},{"id":"er-060","level":3,"segments":["The survey results","collected this week","indicates","a clear trend"],"answer":2,"correction":"indicate","category":"Subject–Verb Agreement","explanation":"The plural subject 'results' requires the plural verb 'indicate'.","rule":"plural subject + base verb","wolf":false},{"id":"er-061","level":3,"segments":["No sooner","the train had left","than the storm","began"],"answer":1,"correction":"had the train left","category":"Inversion","explanation":"After 'no sooner' at the beginning, invert the auxiliary and subject.","rule":"No sooner had + subject + pp + than","wolf":false},{"id":"er-062","level":3,"segments":["The more carefully","you plan,","the fewer mistakes","you will make them"],"answer":3,"correction":"you will make","category":"Pronoun Redundancy","explanation":"The object 'mistakes' is already expressed, so the extra pronoun 'them' is redundant.","rule":"comparative correlative without repeated object","wolf":false},{"id":"er-063","level":3,"segments":["It is essential","that every applicant","is","present at the interview"],"answer":2,"correction":"be","category":"Subjunctive","explanation":"After expressions such as 'it is essential that', formal English uses the base-form subjunctive.","rule":"It is essential that + subject + base verb","wolf":false},{"id":"er-064","level":3,"segments":["The bridge","was built","in order to","improving access"],"answer":3,"correction":"improve access","category":"Infinitive of Purpose","explanation":"'In order to' is followed by the base form of the verb.","rule":"in order to + base verb","wolf":false},{"id":"er-065","level":3,"segments":["The researchers","had the samples","analyze","by an independent lab"],"answer":2,"correction":"analyzed","category":"Causative Have","explanation":"In 'have something done', the object is followed by a past participle.","rule":"have + object + past participle","wolf":false},{"id":"er-066","level":3,"segments":["The committee","consists","in five members","from different departments"],"answer":2,"correction":"of five members","category":"Preposition","explanation":"The verb 'consist' takes the preposition 'of'.","rule":"consist of + components","wolf":false},{"id":"er-067","level":3,"segments":["Each of the proposals","have been reviewed","carefully","by the board"],"answer":1,"correction":"has been reviewed","category":"Subject–Verb Agreement","explanation":"The headword 'each' is singular and takes a singular verb.","rule":"each of + plural noun + singular verb","wolf":false},{"id":"er-068","level":3,"segments":["The reason","why she resigned","was because of","the workload was excessive"],"answer":2,"correction":"was that","category":"Clause Structure","explanation":"'Because of' must be followed by a noun phrase, not the clause 'the workload was excessive'. Here 'was that' correctly introduces the clause.","rule":"the reason ... was that + clause","wolf":false},{"id":"er-069","level":3,"segments":["The company","requires employees","wearing badges","at all times"],"answer":2,"correction":"to wear badges","category":"Verb Complement","explanation":"'Require someone' is followed by a to-infinitive.","rule":"require + object + to-infinitive","wolf":false},{"id":"er-070","level":3,"segments":["The students","were accustomed","to study","late at night"],"answer":2,"correction":"to studying","category":"Gerund after Preposition","explanation":"In 'be accustomed to', 'to' is a preposition and takes a gerund.","rule":"be accustomed to + verb-ing","wolf":false},{"id":"er-071","level":3,"segments":["The museum","where we visited","last year","has reopened"],"answer":1,"correction":"that we visited","category":"Relative Clauses","explanation":"'Visit' takes a direct object; use 'that/which' rather than the place adverb 'where'.","rule":"visit + object; place where + clause","wolf":false},{"id":"er-072","level":3,"segments":["The professor asked","the students","what did they learn","from the experiment"],"answer":2,"correction":"what they learned","category":"Indirect Questions","explanation":"A noun clause uses statement word order, not interrogative inversion.","rule":"what + subject + verb","wolf":false},{"id":"er-073","level":3,"segments":["The machine","needs","to be repaired","before using it again"],"answer":3,"correction":"before it is used again","category":"Reduced Clauses","explanation":"The understood subject of 'using' would be the machine, but a machine cannot use itself. Use a passive clause.","rule":"before + subject + passive verb","wolf":true},{"id":"er-074","level":3,"segments":["Although","the weather was severe,","but the flight","departed on time"],"answer":2,"correction":"the flight","category":"Concession","explanation":"Do not use both 'although' and 'but' to connect the same two clauses.","rule":"although + clause, clause","wolf":false},{"id":"er-075","level":3,"segments":["So difficult","the problem was","that only two students","solved it"],"answer":1,"correction":"was the problem","category":"Inversion","explanation":"When 'so + adjective' is fronted for emphasis, formal English uses subject-auxiliary inversion.","rule":"So + adjective + be + subject + that","wolf":true},{"id":"er-076","level":4,"segments":["Rarely","people realize","how much energy","the process requires"],"answer":1,"correction":"do people realize","category":"Inversion","explanation":"A fronted negative-frequency adverb such as 'rarely' triggers subject-auxiliary inversion.","rule":"Rarely do + subject + base verb","wolf":true},{"id":"er-077","level":4,"segments":["Only after the meeting","the manager understood","the seriousness","of the issue"],"answer":1,"correction":"did the manager understand","category":"Inversion","explanation":"A fronted 'only + adverbial' expression triggers inversion in the main clause.","rule":"Only after... did + subject + base verb","wolf":true},{"id":"er-078","level":4,"segments":["Were the company","to reduce prices,","demand will increase","rapidly"],"answer":2,"correction":"demand would increase","category":"Inverted Conditional","explanation":"'Were + subject + to...' expresses a hypothetical condition and pairs with 'would' in the result.","rule":"Were + subject + to..., subject would + verb","wolf":true},{"id":"er-079","level":4,"segments":["The proposal","is believed","having been rejected","by the committee"],"answer":2,"correction":"to have been rejected","category":"Passive Reporting","explanation":"After 'is believed', use a to-infinitive; for an earlier event, use the perfect infinitive.","rule":"be believed to have + past participle","wolf":false},{"id":"er-080","level":4,"segments":["Scarcely had","the lecture begun","than the fire alarm","sounded"],"answer":2,"correction":"when the fire alarm","category":"Correlative Conjunctions","explanation":"The standard pair is 'scarcely...when', not 'scarcely...than'.","rule":"scarcely...when","wolf":false},{"id":"er-081","level":4,"segments":["Had the researchers","followed the protocol,","the error would not occur","during testing"],"answer":2,"correction":"the error would not have occurred","category":"Inverted Conditional","explanation":"This is an unreal past condition, so the result requires 'would have + past participle'.","rule":"Had + subject + pp, would have + pp","wolf":false},{"id":"er-082","level":4,"segments":["The report","is both","accurate in its data","and it is clearly organized"],"answer":3,"correction":"and clearly organized","category":"Parallelism","explanation":"Elements joined by 'both...and' should have parallel grammatical form; here both should be adjective phrases.","rule":"both + adjective phrase + and + adjective phrase","wolf":false},{"id":"er-083","level":4,"segments":["Not until the final chapter","the author reveals","the identity","of the narrator"],"answer":1,"correction":"does the author reveal","category":"Inversion","explanation":"A fronted 'not until' phrase triggers inversion in the main clause.","rule":"Not until... does + subject + base verb","wolf":true},{"id":"er-084","level":4,"segments":["It was the first time","that she has presented","her findings","at an international conference"],"answer":1,"correction":"that she had presented","category":"Past Perfect","explanation":"When the reference point is in the past ('It was the first time'), the earlier experience is commonly expressed with the past perfect.","rule":"It was the first time + past perfect","wolf":false},{"id":"er-085","level":4,"segments":["The director demanded","that the contract","was revised","before signing"],"answer":2,"correction":"be revised","category":"Subjunctive","explanation":"After 'demand that', formal English uses the base-form subjunctive, including passive 'be + past participle'.","rule":"demand that + subject + be + past participle","wolf":false},{"id":"er-086","level":4,"segments":["The more frequently","the device is used,","the fastest","the battery drains"],"answer":2,"correction":"the faster","category":"Comparative Correlative","explanation":"The pattern requires comparative forms on both sides: 'the more..., the faster...'.","rule":"the + comparative..., the + comparative...","wolf":false},{"id":"er-087","level":4,"segments":["Neither the methodology","nor the conclusions","appears","sufficiently justified"],"answer":2,"correction":"appear","category":"Subject–Verb Agreement","explanation":"With 'neither...nor', the verb commonly agrees with the nearer plural subject 'conclusions'.","rule":"agreement with nearer subject","wolf":false},{"id":"er-088","level":4,"segments":["Having warned","about the storm,","the hikers","decided to continue upward"],"answer":0,"correction":"Having been warned","category":"Participial Clauses","explanation":"The hikers received the warning, so the introductory perfect participle must be passive.","rule":"Having been + past participle","wolf":false},{"id":"er-089","level":4,"segments":["The policy requires","that every transaction","is recorded","electronically"],"answer":2,"correction":"be recorded","category":"Subjunctive","explanation":"After 'require that', formal English uses the base-form subjunctive; the passive form is 'be recorded'.","rule":"require that + subject + be + past participle","wolf":false},{"id":"er-090","level":4,"segments":["Much as","I admire the design,","but I cannot recommend","the product"],"answer":2,"correction":"I cannot recommend","category":"Concession","explanation":"'Much as' already introduces a concessive clause, so 'but' is unnecessary.","rule":"Much as + clause, main clause","wolf":false},{"id":"er-091","level":4,"segments":["The results were","such surprising","that the team","repeated the test"],"answer":1,"correction":"so surprising","category":"So vs Such","explanation":"Use 'so + adjective'; 'such' normally modifies a noun phrase.","rule":"so + adjective + that","wolf":false},{"id":"er-092","level":4,"segments":["Seldom","the committee has faced","a decision","this controversial"],"answer":1,"correction":"has the committee faced","category":"Inversion","explanation":"A fronted negative-frequency adverb triggers auxiliary-subject inversion.","rule":"Seldom has + subject + past participle","wolf":true},{"id":"er-093","level":4,"segments":["It is high time","the government takes","stronger measures","to reduce pollution"],"answer":1,"correction":"the government took","category":"Unreal Past","explanation":"After 'it is high time', English conventionally uses a past form to express a present recommendation or overdue action.","rule":"It is high time + subject + past verb","wolf":false},{"id":"er-094","level":4,"segments":["Had it not been","for the backup system,","the entire database would be lost","during the outage"],"answer":2,"correction":"the entire database would have been lost","category":"Inverted Conditional","explanation":"The condition refers to an unreal past situation, so the result requires the conditional perfect.","rule":"Had it not been for..., would have + past participle","wolf":false},{"id":"er-095","level":4,"segments":["The researchers found","the new method","to be more efficient","as the old one"],"answer":3,"correction":"than the old one","category":"Comparison","explanation":"The comparative 'more efficient' is followed by 'than'.","rule":"comparative + than","wolf":false},{"id":"er-096","level":4,"segments":["What the committee needs","are","more reliable evidence","before deciding"],"answer":1,"correction":"is","category":"Subject–Verb Agreement","explanation":"The noun clause 'What the committee needs' functions as a singular subject.","rule":"what-clause as singular subject + singular verb","wolf":false},{"id":"er-097","level":4,"segments":["The experiment was designed","not only to measure accuracy","but also evaluating","response time"],"answer":2,"correction":"but also to evaluate","category":"Parallelism","explanation":"The structures after 'not only' and 'but also' should be parallel to-infinitives.","rule":"not only to + verb, but also to + verb","wolf":false},{"id":"er-098","level":4,"segments":["No matter how carefully","the instructions are written,","there is always users","who misunderstand them"],"answer":2,"correction":"there are always users","category":"Subject–Verb Agreement","explanation":"The existential verb agrees with the following plural noun 'users'.","rule":"there are + plural noun","wolf":false},{"id":"er-099","level":4,"segments":["Under no circumstances","employees should disclose","confidential information","to unauthorized persons"],"answer":1,"correction":"should employees disclose","category":"Inversion","explanation":"A fronted negative expression such as 'under no circumstances' triggers subject-auxiliary inversion.","rule":"Under no circumstances should + subject + base verb","wolf":true},{"id":"er-100","level":4,"segments":["Were it not","for the scholarship,","she cannot afford","to continue her studies"],"answer":2,"correction":"she could not afford","category":"Hypothetical Condition","explanation":"'Were it not for' expresses a present hypothetical condition, so the result normally uses 'would/could'.","rule":"Were it not for..., could/would + base verb","wolf":true}];
const STORAGE='error-recognition-pasture-v1';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),toast=document.querySelector('#toast');
let db=load(),current=null,practicePool=[],practiceIndex=0,selected=null,checked=false,hintsUsed=0;
let exam={active:false,pool:[],index:0,answers:[],started:0,duration:15*60,timer:null};
let audioCtx=null,musicTimer=null;

function load(){try{let x=JSON.parse(localStorage.getItem(STORAGE));if(x&&Array.isArray(x.questions))return normalize(x)}catch(e){}return normalize({questions:structuredClone(STARTERS),attempts:[],theme:'light',music:false,sfx:true,streak:0,lastDay:null})}
function normalize(x){x.questions=x.questions||structuredClone(STARTERS);x.attempts=x.attempts||[];x.theme=x.theme||'light';x.music=!!x.music;x.sfx=x.sfx!==false;x.streak=x.streak||0;x.lastDay=x.lastDay||null;return x}
function save(){localStorage.setItem(STORAGE,JSON.stringify(db));document.documentElement.dataset.theme=db.theme;syncControls()}
function esc(s=''){return String(s).replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function sentenceText(q){return q.segments.join(' ')}
function beep(freq=520,d=.06){if(!db.sfx)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;g.gain.value=.035;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+d);o.stop(audioCtx.currentTime+d)}catch(e){}}
function toggleMusic(){db.music=!db.music;if(db.music)startMusic();else stopMusic();save()}
function startMusic(){try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();stopMusic();const notes=[261.6,329.6,392,329.6,293.7,349.2,440,349.2];let i=0;musicTimer=setInterval(()=>{if(!db.music)return;let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=notes[i++%notes.length]/2;g.gain.value=.008;o.connect(g);g.connect(audioCtx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.8);o.stop(audioCtx.currentTime+.85)},1100)}catch(e){}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null}
function syncControls(){document.querySelector('#themeBtn').textContent=db.theme==='light'?'☀':'☾';document.querySelector('#musicBtn').classList.toggle('active',db.music);document.querySelector('#musicBtn').textContent=db.music?'♫':'♪';document.querySelector('#sfxBtn').classList.toggle('active',db.sfx);document.querySelector('#sfxBtn').textContent=db.sfx?'🔊':'🔇'}
document.documentElement.dataset.theme=db.theme;syncControls();
document.querySelector('#themeBtn').onclick=()=>{db.theme=db.theme==='light'?'dark':'light';save()};
document.querySelector('#musicBtn').onclick=toggleMusic;document.querySelector('#sfxBtn').onclick=()=>{db.sfx=!db.sfx;save();beep(660)};
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
function go(view){stopExam();if(view==='home')renderHome();if(view==='practice')renderPracticeMenu();if(view==='bank')renderBank();if(view==='stats')renderStats()}
function accuracy(arr=db.attempts){return arr.length?Math.round(arr.filter(a=>a.correct).length*100/arr.length):0}
function updateStreak(){let d=new Date().toISOString().slice(0,10);if(db.lastDay===d)return;let y=new Date(Date.now()-86400000).toISOString().slice(0,10);db.streak=db.lastDay===y?db.streak+1:1;db.lastDay=d}
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}

function renderHome(){let attempts=db.attempts.length,acc=accuracy(),seen=new Set(db.attempts.map(a=>a.id)).size;app.innerHTML=`<section class="hero"><div class="hero-card hero-copy"><span class="eyebrow">Find the grammar wolf</span><h1>Error <em>Recognition</em> Pasture</h1><p>Read one sentence with four underlined parts. Choose the single part that must change for the sentence to be grammatically correct, then study the correction and rule.</p><div class="hero-actions"><button class="btn primary" onclick="renderPracticeMenu()">Start practice</button><button class="btn" onclick="startExam()">25-question timed drill</button></div><div class="legend"><span>A–D clickable underlined parts</span><span>3-level hints</span><span>correction + grammar rule</span><span>CRUD question bank</span></div></div><div class="hero-card mascot-card"><div class="mascot">🐑</div><div class="wolf-peek">🐺</div><h3>One wolf is hiding in every sentence.</h3><p>Do not rewrite the whole sentence first. Identify the faulty segment, then explain why it fails.</p><div class="mini-stats"><div class="mini-stat"><strong>${attempts}</strong><span>attempts</span></div><div class="mini-stat"><strong>${acc}%</strong><span>accuracy</span></div><div class="mini-stat"><strong>${seen}</strong><span>seen / ${db.questions.length}</span></div></div></div></section><div class="section-head"><div><h2>Training trails</h2><p>Difficulty rises from obvious form errors to inversion, parallelism and hypothetical structures.</p></div></div><div class="mode-grid">${[1,2,3,4].map((l,i)=>`<button class="mode-card" onclick="startPractice(${l})"><span class="icon">${['🌱','🌾','🐑','🐺'][i]}</span><h3>${['Seedling','Meadow','Shepherd','Wolf Trail'][i]}</h3><p>${['Agreement, articles, basic verb forms and adjective/adverb choice.','Tense, complements, comparisons, relative clauses and pronouns.','Formal clauses, subjunctive, modifiers, passive forms and inversion.','Advanced inversion, unreal conditions, parallelism and high-risk structures.'][i]}</p><span class="level-chip">25 starter questions</span></button>`).join('')}</div><div class="panel" style="padding:22px;margin-top:18px"><b>Format note.</b><p style="color:var(--muted);line-height:1.6;margin-bottom:0">This is an original practice companion inspired by the TOEFL ITP Written Expression task format. It is not an ETS product, and its internal scores are not TOEFL scores.</p></div>`}

function renderPracticeMenu(){app.innerHTML=`<div class="section-head"><div><h2>Choose a trail</h2><p>Practice by level, mix all questions, or run a timed 25-question drill.</p></div></div><div class="mode-grid"><button class="mode-card" onclick="startPractice(0)"><span class="icon">🌿</span><h3>Mixed Practice</h3><p>Shuffle the entire question bank.</p><span class="level-chip">${db.questions.length} questions</span></button>${[1,2,3,4].map((l,i)=>`<button class="mode-card" onclick="startPractice(${l})"><span class="icon">${['🌱','🌾','🐑','🐺'][i]}</span><h3>Level ${l}</h3><p>${['Basic grammar recognition','Intermediate sentence patterns','Upper-intermediate structure','Advanced grammar traps'][i]}</p><span class="level-chip">${db.questions.filter(q=>q.level===l).length} questions</span></button>`).join('')}<button class="mode-card" onclick="startExam()"><span class="icon">⏱</span><h3>Timed Drill</h3><p>25 random items in 15 minutes. Internal practice mode only.</p><span class="level-chip">25 questions</span></button></div>`}
function startPractice(level=0){stopExam();practicePool=db.questions.filter(q=>!level||q.level===level).sort(()=>Math.random()-.5);practiceIndex=0;nextQuestion()}
function nextQuestion(){if(!practicePool.length){renderHome();return}current=practicePool[practiceIndex%practicePool.length];selected=null;checked=false;hintsUsed=0;renderQuestion()}
function segmentButtons(q){return q.segments.map((s,i)=>`<button class="segment ${selected===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&selected===i&&i!==q.answer?'chosen-wrong':''}" onclick="pick(${i})" ${checked?'disabled':''}><span class="seg-text">${esc(s)}</span><span class="seg-label">(${'ABCD'[i]})</span></button>`).join(' ')}
function hintText(q,n){if(n===0)return `Focus on ${q.category.toLowerCase()}. Ask what grammatical relationship controls the four marked parts.`;if(n===1)return `The error is in part (${'ABCD'[q.answer]}). Inspect “${esc(q.segments[q.answer])}” carefully.`;return `Part (${'ABCD'[q.answer]}) should be changed to “${esc(q.correction)}”.`}
function renderQuestion(){let q=current;app.innerHTML=`<div class="section-head"><div><h2>${q.level===4?'🐺 Wolf Trail':'Error Recognition'}</h2><p>Level ${q.level} · ${esc(q.category)} · Question ${practiceIndex+1}/${practicePool.length}</p></div><button class="btn ghost" onclick="renderHome()">Exit</button></div><div class="practice-layout"><section class="question-card"><div class="question-top"><span class="tag">${q.wolf?'🐺 WOLF QUESTION':'🐑 FIND THE ERROR'}</span><span class="tag">${esc(q.category)}</span></div><div class="progress-line"><span style="width:${100*(practiceIndex+1)/practicePool.length}%"></span></div><p class="notice">Select the one underlined word or phrase that must be changed. Keyboard: <span class="kbd">A</span> <span class="kbd">B</span> <span class="kbd">C</span> <span class="kbd">D</span>, then <span class="kbd">Enter</span>.</p><div class="error-sentence">${segmentButtons(q)}.</div>${checked?`<div class="result-box"><h3>${selected===q.answer?'✓ Correct':'Correct answer: ('+'ABCD'[q.answer]+')'}</h3><p>${esc(q.explanation)}</p><div class="correction-card"><div><span class="before">${esc(q.segments[q.answer])}</span> → <span class="after">${esc(q.correction)}</span></div><span class="rule-chip">${esc(q.rule)}</span></div></div>`:''}<div class="practice-actions">${checked?`<button class="btn primary" onclick="advance()">Next question →</button>`:`<button class="btn primary" onclick="checkAnswer()" ${selected===null?'disabled':''}>Check answer</button>`}<span>${checked?'Correction shown above.':'You may reveal hints if needed.'}</span></div></section><aside class="panel side-panel"><h3>💡 Hint ladder</h3><div class="hint-stack">${[0,1,2].map(i=>`<div class="hint-box"><b>Hint ${i+1}</b><br>${hintsUsed>i?hintText(q,i):`<button class="btn ghost" onclick="useHint()">Reveal</button>`}</div>`).join('')}</div>${q.wolf?`<div class="wolf-note"><b>Wolf trap.</b> This question tests a structure that often looks acceptable in casual reading. Check syntax, not only meaning.</div>`:''}</aside></div>`}
window.pick=i=>{if(checked)return;selected=i;beep(420);renderQuestion()};window.useHint=()=>{if(hintsUsed<3)hintsUsed++;renderQuestion()};window.checkAnswer=()=>{if(selected===null)return;checked=true;let correct=selected===current.answer;db.attempts.push({id:current.id,correct,level:current.level,category:current.category,hints:hintsUsed,ts:Date.now()});updateStreak();save();beep(correct?720:220,.1);renderQuestion()};window.advance=()=>{practiceIndex++;if(practiceIndex>=practicePool.length){showToast('Trail complete');renderStats()}else nextQuestion()};
window.addEventListener('keydown',e=>{if(exam.active)return;if(!current||checked)return;let k=e.key.toUpperCase();if('ABCD'.includes(k)){selected='ABCD'.indexOf(k);beep(420);renderQuestion()}else if(e.key==='Enter'&&selected!==null)checkAnswer()});

function startExam(){stopExam();let pool=db.questions.slice().sort(()=>Math.random()-.5).slice(0,25);exam={active:true,pool,index:0,answers:Array(25).fill(null),started:Date.now(),duration:15*60,timer:null};renderExamQuestion();exam.timer=setInterval(()=>{if(!exam.active)return;let left=exam.duration-Math.floor((Date.now()-exam.started)/1000);let el=document.querySelector('#examTimer');if(el){el.textContent=formatTime(Math.max(0,left));el.classList.toggle('danger',left<120)}if(left<=0)finishExam()},1000)}
function stopExam(){if(exam.timer)clearInterval(exam.timer);exam.timer=null;exam.active=false}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function renderExamQuestion(){if(!exam.active)return;let q=exam.pool[exam.index],sel=exam.answers[exam.index];app.innerHTML=`<div class="section-head"><div><h2>⏱ Timed Error Drill</h2><p>25 original practice items · internal training score only</p></div><button class="btn ghost" onclick="finishExam(true)">End drill</button></div><div class="exam-banner"><div><b>Question ${exam.index+1} / 25</b><div class="progress-line" style="width:min(360px,70vw);margin:8px 0 0"><span style="width:${100*(exam.index+1)/25}%"></span></div></div><div id="examTimer" class="timer">${formatTime(exam.duration-Math.floor((Date.now()-exam.started)/1000))}</div></div><section class="question-card"><span class="tag">${q.wolf?'🐺 WOLF QUESTION':'A–D ERROR IDENTIFICATION'}</span><div class="error-sentence">${q.segments.map((s,i)=>`<button class="segment ${sel===i?'selected':''}" onclick="examPick(${i})"><span class="seg-text">${esc(s)}</span><span class="seg-label">(${'ABCD'[i]})</span></button>`).join(' ')}.</div><div class="practice-actions"><button class="btn" onclick="examPrev()" ${exam.index===0?'disabled':''}>← Previous</button><span>${exam.answers.filter(x=>x!==null).length} / 25 answered</span><button class="btn primary" onclick="examNext()">${exam.index===24?'Finish':'Next →'}</button></div></section>`}
window.examPick=i=>{exam.answers[exam.index]=i;beep(450);renderExamQuestion()};window.examPrev=()=>{if(exam.index>0)exam.index--;renderExamQuestion()};window.examNext=()=>{if(exam.index===24)finishExam();else{exam.index++;renderExamQuestion()}};
window.finishExam=(early=false)=>{if(!exam.active)return;if(early&&!confirm('End this timed drill now?'))return;let elapsed=Math.min(exam.duration,Math.floor((Date.now()-exam.started)/1000)),items=exam.pool.map((q,i)=>({q,sel:exam.answers[i],correct:exam.answers[i]===q.answer}));items.forEach(x=>{if(x.sel!==null)db.attempts.push({id:x.q.id,correct:x.correct,level:x.q.level,category:x.q.category,hints:0,exam:true,ts:Date.now()})});updateStreak();save();let correct=items.filter(x=>x.correct).length,answered=items.filter(x=>x.sel!==null).length;stopExam();app.innerHTML=`<div class="section-head"><div><h2>Timed Drill Complete</h2><p>This is an internal practice result, not a TOEFL score.</p></div></div><section class="panel" style="padding:28px"><p class="score-big">${correct} / 25</p><div class="exam-results"><div><strong>${Math.round(correct*100/25)}%</strong><span>raw accuracy</span></div><div><strong>${answered}</strong><span>answered</span></div><div><strong>${formatTime(elapsed)}</strong><span>time used</span></div></div><h3>Review missed items</h3><div class="bank-list">${items.filter(x=>!x.correct).slice(0,12).map(x=>`<div class="bank-card"><div><h3 class="bank-segments">${x.q.segments.map((s,i)=>`<u>${esc(s)}</u> (${'ABCD'[i]})`).join(' ')}</h3><p>Correct error: <b>(${'ABCD'[x.q.answer]})</b> · ${esc(x.q.segments[x.q.answer])} → ${esc(x.q.correction)}</p><span class="tag">${esc(x.q.category)}</span></div></div>`).join('')||'<div class="empty">Perfect trail. No missed items.</div>'}</div><div class="hero-actions"><button class="btn primary" onclick="startExam()">New timed drill</button><button class="btn" onclick="renderStats()">View progress</button></div></section>`}

function renderBank(){app.innerHTML=`<div class="section-head"><div><h2>Question Bank</h2><p>Create, edit, duplicate and delete A–D error-recognition questions.</p></div><button class="btn primary" onclick="editQuestion()">+ Add question</button></div><div class="toolbar"><input id="search" placeholder="Search sentence or grammar rule…"><select id="levelFilter"><option value="0">All levels</option>${[1,2,3,4].map(l=>`<option value="${l}">Level ${l}</option>`).join('')}</select><button class="btn" onclick="exportData()">Export JSON</button><button class="btn" onclick="document.querySelector('#importFile').click()">Import</button><button class="btn danger" onclick="restoreStarters()">Restore 100</button><input id="importFile" type="file" accept="application/json" hidden></div><div id="bankList" class="bank-list" style="margin-top:16px"></div>`;let s=document.querySelector('#search'),f=document.querySelector('#levelFilter');let draw=()=>{let term=s.value.toLowerCase(),lv=+f.value;let arr=db.questions.filter(q=>(!lv||q.level===lv)&&(!term||(sentenceText(q)+' '+q.category+' '+q.rule).toLowerCase().includes(term)));document.querySelector('#bankList').innerHTML=arr.map(q=>`<div class="bank-card"><div><h3 class="bank-segments">${q.segments.map((x,i)=>`<u>${esc(x)}</u> (${'ABCD'[i]})`).join(' ')}</h3><p>Level ${q.level} · ${esc(q.category)} · Error: <b>(${'ABCD'[q.answer]})</b> · Correction: ${esc(q.correction)}</p><span class="tag">${esc(q.rule)}</span></div><div class="card-actions"><button class="icon-btn" onclick="editQuestion('${q.id}')">✎</button><button class="icon-btn" onclick="duplicateQuestion('${q.id}')">⧉</button><button class="icon-btn" onclick="deleteQuestion('${q.id}')">🗑</button></div></div>`).join('')||'<div class="empty">No matching questions.</div>'};s.oninput=f.onchange=draw;draw();document.querySelector('#importFile').onchange=importData}
window.editQuestion=id=>{let q=id?db.questions.find(x=>x.id===id):{id:'er-'+Date.now(),level:1,segments:['','','',''],answer:0,correction:'',category:'Subject–Verb Agreement',explanation:'',rule:'',wolf:false};modal.classList.remove('hidden');modal.innerHTML=`<div class="modal"><h2>${id?'Edit':'Add'} question</h2><p class="notice">Enter four underlined parts in sentence order. Exactly one part must be grammatically wrong.</p><div class="form-grid">${q.segments.map((x,i)=>`<label>Part ${'ABCD'[i]} <input class="mSeg" value="${esc(x)}"></label>`).join('')}<label>Incorrect part <select id="mAnswer">${[0,1,2,3].map(i=>`<option value="${i}" ${q.answer===i?'selected':''}>${'ABCD'[i]}</option>`).join('')}</select></label><label>Correct replacement <input id="mCorrection" value="${esc(q.correction)}"></label><label>Level <select id="mLevel">${[1,2,3,4].map(l=>`<option value="${l}" ${q.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Category <input id="mCategory" value="${esc(q.category)}"></label><label>Grammar rule <input id="mRule" value="${esc(q.rule)}"></label><label class="full">Explanation <textarea id="mExplanation" rows="4">${esc(q.explanation)}</textarea></label><label><span><input type="checkbox" id="mWolf" ${q.wolf?'checked':''}> Wolf question</span></label></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveQuestion('${q.id}')">Save</button></div></div>`}
window.closeModal=()=>modal.classList.add('hidden');modal.onclick=e=>{if(e.target===modal)closeModal()};
window.saveQuestion=id=>{let segs=[...document.querySelectorAll('.mSeg')].map(x=>x.value.trim());if(segs.some(x=>!x))return showToast('Fill all four parts');let q={id,segments:segs,answer:+document.querySelector('#mAnswer').value,correction:document.querySelector('#mCorrection').value.trim(),level:+document.querySelector('#mLevel').value,category:document.querySelector('#mCategory').value.trim(),rule:document.querySelector('#mRule').value.trim(),explanation:document.querySelector('#mExplanation').value.trim(),wolf:document.querySelector('#mWolf').checked};if(!q.correction||!q.category||!q.rule||!q.explanation)return showToast('Complete correction and explanation');let i=db.questions.findIndex(x=>x.id===id);if(i>=0)db.questions[i]=q;else db.questions.push(q);save();closeModal();renderBank();showToast('Question saved')};
window.duplicateQuestion=id=>{let q=db.questions.find(x=>x.id===id);if(!q)return;let c=structuredClone(q);c.id='er-'+Date.now();db.questions.push(c);save();renderBank();showToast('Question duplicated')};window.deleteQuestion=id=>{if(!confirm('Delete this question?'))return;db.questions=db.questions.filter(q=>q.id!==id);save();renderBank()};
window.restoreStarters=()=>{if(!confirm('Replace the current question bank with the original 100 starter questions? Progress will be kept.'))return;db.questions=structuredClone(STARTERS);save();renderBank();showToast('100 starters restored')};
window.exportData=()=>{let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='error-recognition-pasture-backup.json';a.click();URL.revokeObjectURL(a.href)};function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!Array.isArray(x.questions))throw 0;db=normalize(x);save();renderBank();showToast('Import complete')}catch(err){showToast('Invalid backup')}};r.readAsText(f)}

function renderStats(){let total=db.attempts.length,acc=accuracy(),unique=new Set(db.attempts.map(a=>a.id)).size;let byLevel=[1,2,3,4].map(l=>{let a=db.attempts.filter(x=>x.level===l);return{l,n:a.length,acc:a.length?Math.round(100*a.filter(x=>x.correct).length/a.length):0}});let cats={};db.attempts.forEach(a=>{cats[a.category]??={n:0,c:0};cats[a.category].n++;if(a.correct)cats[a.category].c++});let weak=Object.entries(cats).filter(([k,v])=>v.n>=2).map(([k,v])=>({k,n:v.n,acc:Math.round(100*v.c/v.n)})).sort((a,b)=>a.acc-b.acc).slice(0,6);app.innerHTML=`<div class="section-head"><div><h2>Progress</h2><p>Use this diagnostically. Accuracy here is not a standardized TOEFL score.</p></div><button class="btn" onclick="resetProgress()">Reset progress</button></div><div class="stats-grid"><div class="stat-card"><strong>${total}</strong><span>attempts</span></div><div class="stat-card"><strong>${acc}%</strong><span>overall accuracy</span></div><div class="stat-card"><strong>${unique}</strong><span>questions encountered</span></div><div class="stat-card"><strong>${db.streak}</strong><span>day streak</span></div></div><div class="panel" style="padding:22px;margin-top:18px"><h3>Accuracy by level</h3><div class="level-progress">${byLevel.map(x=>`<div class="level-row"><b>Level ${x.l}</b><div class="bar"><span style="width:${x.acc}%"></span></div><span>${x.acc}%</span></div>`).join('')}</div></div><div class="panel" style="padding:22px;margin-top:18px"><h3>Weak-area notebook</h3>${weak.length?`<div class="weak-grid">${weak.map(x=>`<div class="weak-card"><strong>${esc(x.k)}</strong><span>${x.acc}% correct across ${x.n} attempts</span></div>`).join('')}</div>`:'<p>No stable weak area yet. Complete more questions.</p>'}</div><div class="panel" style="padding:22px;margin-top:18px"><h3>Grammar categories</h3>${Object.entries(cats).length?Object.entries(cats).sort((a,b)=>b[1].n-a[1].n).map(([k,v])=>`<p><b>${esc(k)}</b> · ${v.n} attempts · ${Math.round(100*v.c/v.n)}% correct</p>`).join(''):'<p>No attempts yet.</p>'}</div>`}
window.resetProgress=()=>{if(confirm('Reset attempts and streak?')){db.attempts=[];db.streak=0;db.lastDay=null;save();renderStats()}};
renderHome();
